/**
 * Graph Enricher - 图谱丰富模块
 * 搜索并关联关键论文到知识图谱中的概念
 */

import LiteratureSearch from '../../literature-search/scripts/search';
import ReviewDetector from '../../review-detector/scripts/detect';
import KnowledgeGraphIndexer from './indexer';
import type { SearchResult } from '../../literature-search/scripts/types';
import type { ExtractedConcept } from '../../concept-extractor/scripts/types';
import type {
  KnowledgeGraphData,
  PaperMetadata,
  LiteratureReference
} from './graph';

/**
 * 丰富选项
 */
export interface EnrichOptions {
  /** 每个概念搜索的论文数 */
  papersPerConcept?: number;
  /** 最小引用数过滤 */
  minCitations?: number;
  /** 最小相关度阈值 */
  minRelevance?: number;
  /** 是否过滤掉综述 */
  filterReviews?: boolean;
  /** 搜索数据源 */
  sources?: ('arxiv' | 'semantic_scholar' | 'web')[];
}

export default class GraphEnricher {
  private searcher: LiteratureSearch;
  private detector: ReviewDetector;
  private indexer: KnowledgeGraphIndexer;

  constructor() {
    this.searcher = new LiteratureSearch();
    this.detector = new ReviewDetector();
    this.indexer = new KnowledgeGraphIndexer();
  }

  async initialize(): Promise<void> {
    await this.searcher.initialize();
    // detector初始化延迟到需要AI判断时
  }

  /**
   * 为图谱中的概念搜索并关联关键论文
   */
  async enrichWithKeyPapers(
    graph: KnowledgeGraphData,
    concepts: ExtractedConcept[],
    options: EnrichOptions = {}
  ): Promise<KnowledgeGraphData> {
    const {
      papersPerConcept = 5,
      minCitations = 0,
      minRelevance = 0.3,
      filterReviews = true,
      sources = ['arxiv', 'semantic_scholar']
    } = options;

    console.log('\n🔍 搜索关键论文...');

    let totalAssociated = 0;

    for (const concept of concepts) {
      try {
        // 搜索论文
        const searchResults = await this.searcher.search(concept.name, {
          limit: papersPerConcept * 2, // 多搜索一些以备过滤
          sources,
          sortBy: 'citations',
          filters: { minCitations }
        });

        let candidatePapers = searchResults.results;

        // 过滤综述（只保留研究论文）
        if (filterReviews) {
          candidatePapers = await this.filterOutReviews(candidatePapers);
        }

        // 取前N篇
        const keyPapers = candidatePapers.slice(0, papersPerConcept);

        // 找到图谱中对应的节点
        const node = graph.nodes.find(n =>
          n.label === concept.name ||
          n.label === concept.nameEn ||
          n.label === concept.nameZh
        );

        if (!node) continue;

        let conceptAssociated = 0;

        for (const paper of keyPapers) {
          const relevance = this.calculateRelevance(paper, concept);
          if (relevance < minRelevance) continue;

          const paperMetadata: PaperMetadata = {
            id: paper.id,
            title: paper.title,
            authors: paper.authors,
            abstract: paper.abstract,
            publishDate: paper.publishDate,
            url: paper.url,
            pdfUrl: paper.pdfUrl,
            citations: paper.citations,
            paperType: 'research',
            keywords: paper.keywords || []
          };

          const reference: LiteratureReference = {
            paperId: paper.id,
            title: paper.title,
            relevance,
            mentionType: this.determineMentionType(concept, paper),
            contexts: []
          };

          this.indexer.addPaperToIndex(graph, node.id, paperMetadata, reference);
          conceptAssociated++;
          totalAssociated++;
        }

        console.log(`  ✓ ${concept.name}: 关联 ${conceptAssociated} 篇关键论文`);
      } catch (error) {
        console.error(`  ✗ ${concept.name}: 搜索失败 - ${error instanceof Error ? error.message : String(error)}`);
      }
    }

    console.log(`\n📊 共关联 ${totalAssociated} 篇关键论文`);

    // 重建索引
    this.indexer.buildIndex(graph);

    return graph;
  }

  /**
   * 添加综述论文到图谱
   */
  addReviewToGraph(
    graph: KnowledgeGraphData,
    review: SearchResult,
    relatedConceptIds: string[]
  ): void {
    const paperMetadata: PaperMetadata = {
      id: review.id,
      title: review.title,
      authors: review.authors,
      abstract: review.abstract,
      publishDate: review.publishDate,
      url: review.url,
      pdfUrl: review.pdfUrl,
      citations: review.citations,
      paperType: 'review',
      keywords: review.keywords || []
    };

    for (const conceptId of relatedConceptIds) {
      const reference: LiteratureReference = {
        paperId: review.id,
        title: review.title,
        relevance: 0.9, // 综述与其提取的概念高度相关
        mentionType: 'foundational',
        contexts: []
      };

      this.indexer.addPaperToIndex(graph, conceptId, paperMetadata, reference);
    }
  }

  /**
   * 过滤掉综述论文
   */
  private async filterOutReviews(papers: SearchResult[]): Promise<SearchResult[]> {
    const result: SearchResult[] = [];

    for (const paper of papers) {
      // 快速启发式检测（不使用AI，速度更快）
      const detection = await this.detector.detectReview(paper, { useAI: false });
      if (!detection.isReview || detection.confidence < 0.5) {
        result.push(paper);
      }
    }

    return result;
  }

  /**
   * 计算论文与概念的相关度
   */
  private calculateRelevance(paper: SearchResult, concept: ExtractedConcept): number {
    let score = 0;

    const titleLower = paper.title.toLowerCase();
    const abstractLower = (paper.abstract || '').toLowerCase();
    const conceptLower = concept.name.toLowerCase();

    // 标题包含概念名 - 高相关
    if (titleLower.includes(conceptLower)) {
      score += 0.4;
    }

    // 摘要包含概念名
    if (abstractLower.includes(conceptLower)) {
      score += 0.2;
    }

    // 检查别名匹配
    for (const alias of concept.aliases) {
      const aliasLower = alias.toLowerCase();
      if (titleLower.includes(aliasLower)) {
        score += 0.2;
        break;
      }
      if (abstractLower.includes(aliasLower)) {
        score += 0.1;
        break;
      }
    }

    // 引用数加分
    if (paper.citations) {
      if (paper.citations >= 500) score += 0.2;
      else if (paper.citations >= 100) score += 0.15;
      else if (paper.citations >= 50) score += 0.1;
      else if (paper.citations >= 10) score += 0.05;
    }

    return Math.min(1, Math.round(score * 100) / 100);
  }

  /**
   * 确定引用类型
   */
  private determineMentionType(
    concept: ExtractedConcept,
    paper: SearchResult
  ): 'foundational' | 'methodological' | 'application' {
    const titleLower = paper.title.toLowerCase();
    const abstractLower = (paper.abstract || '').toLowerCase();
    const text = `${titleLower} ${abstractLower}`;

    // 方法论相关
    const methodKeywords = ['method', 'algorithm', 'approach', 'technique', 'framework', 'architecture',
      '方法', '算法', '技术', '框架', '架构'];
    if (methodKeywords.some(k => text.includes(k))) {
      return 'methodological';
    }

    // 应用相关
    const appKeywords = ['application', 'applied', 'use case', 'deploy', 'system',
      '应用', '部署', '系统', '实践'];
    if (appKeywords.some(k => text.includes(k))) {
      return 'application';
    }

    return 'foundational';
  }
}

/**
 * Knowledge Graph Builder - Core Module
 * 知识图谱构建核心模块
 *
 * 功能：
 * - 从概念列表构建知识图谱
 * - 识别概念间关系
 * - 生成可视化输出
 */

import { createAIProvider, type AIProvider } from '../../shared/ai-provider';
import { extractJson } from '../../shared/utils';
import { ApiInitializationError, getErrorMessage } from '../../shared/errors';

/**
 * 文献引用信息
 */
export interface LiteratureReference {
  /** 论文ID */
  paperId: string;
  /** 论文标题 */
  title: string;
  /** 相关度 (0-1) */
  relevance: number;
  /** 引用类型 */
  mentionType: 'foundational' | 'methodological' | 'application';
  /** 引用上下文 */
  contexts: string[];
}

/**
 * 概念定义（可多来源）
 */
export interface ConceptDefinition {
  /** 定义内容 */
  text: string;
  /** 来源论文ID */
  sourceId: string;
  /** 来源论文标题 */
  sourceTitle: string;
}

/**
 * 论文元数据（用于索引）
 */
export interface PaperMetadata {
  /** 论文ID */
  id: string;
  /** 标题 */
  title: string;
  /** 作者 */
  authors: string[];
  /** 摘要 */
  abstract: string;
  /** 发表日期 */
  publishDate: string;
  /** URL */
  url: string;
  /** PDF URL */
  pdfUrl?: string;
  /** 引用数 */
  citations?: number;
  /** 论文类型 */
  paperType: 'review' | 'research';
  /** 关键词 */
  keywords: string[];
  /** 额外元数据 */
  metadata?: Record<string, unknown>;
}

/**
 * 文献索引（论文→概念映射）
 */
export interface LiteratureIndex {
  /** 论文ID → 论文元数据 */
  papers: Map<string, PaperMetadata>;
  /** 论文ID → 关联概念ID列表 */
  paperToConcepts: Map<string, string[]>;
}

/**
 * 概念索引（概念→论文映射）
 */
export interface ConceptIndex {
  /** 概念ID → 论文引用列表 */
  conceptToPapers: Map<string, LiteratureReference[]>;
}

/**
 * 图谱元数据
 */
export interface GraphMetadata {
  /** 图谱名称 */
  name: string;
  /** 创建时间 */
  createdAt: string;
  /** 更新时间 */
  updatedAt: string;
  /** 来源综述 */
  sourceReviews: string[];
  /** 统计 */
  totalConcepts: number;
  totalPapers: number;
  totalRelations: number;
}

export interface KnowledgeNode {
  id: string;
  label: string;
  category: 'foundation' | 'core' | 'advanced' | 'application';
  importance: number;
  description?: string;
  /** 文献引用列表 */
  literatureReferences?: LiteratureReference[];
  /** 多来源定义 */
  definitions?: ConceptDefinition[];
  /** 关键论文ID */
  keyPapers?: string[];
  /** 节点元数据 */
  metadata?: {
    extractedFrom?: string[];
    lastUpdated?: string;
    confidence?: number;
  };
}

export interface KnowledgeEdge {
  source: string;
  target: string;
  relation: 'prerequisite' | 'related' | 'derived' | 'component';
  label?: string;
}

export interface KnowledgeGraphData {
  nodes: KnowledgeNode[];
  edges: KnowledgeEdge[];
  clusters: Map<string, string[]>;
  /** 文献索引 */
  literatureIndex?: LiteratureIndex;
  /** 概念索引 */
  conceptIndex?: ConceptIndex;
  /** 图谱元数据 */
  graphMetadata?: GraphMetadata;
}

export default class KnowledgeGraphBuilder {
  private ai: AIProvider | null = null;

  async initialize(): Promise<void> {
    if (!this.ai) {
      try {
        this.ai = await createAIProvider();
      } catch (error) {
        throw new ApiInitializationError(
          `Failed to initialize AI provider: ${getErrorMessage(error)}`,
          error instanceof Error ? error : undefined
        );
      }
    }
  }

  /**
   * 从概念列表构建知识图谱
   */
  async build(concepts: string[]): Promise<KnowledgeGraphData> {
    await this.initialize();

    // 识别概念间关系
    const relations = await this.identifyRelations(concepts);

    // 构建节点
    const nodes: KnowledgeNode[] = concepts.map((concept, index) => ({
      id: `node_${index}`,
      label: concept,
      category: this.categorizeConcept(concept, relations),
      importance: this.calculateImportance(concept, relations)
    }));

    // 构建边
    const edges: KnowledgeEdge[] = relations.map(r => ({
      source: nodes.find(n => n.label === r.source)?.id || r.source,
      target: nodes.find(n => n.label === r.target)?.id || r.target,
      relation: r.relation,
      label: r.relation
    }));

    // 构建聚类
    const clusters = this.buildClusters(nodes, edges);

    return { nodes, edges, clusters };
  }

  /**
   * 识别概念间关系
   */
  private async identifyRelations(
    concepts: string[]
  ): Promise<Array<{ source: string; target: string; relation: string }>> {
    const prompt = `分析以下概念之间的关系:

概念列表: ${concepts.join(', ')}

请识别概念之间的依赖和关联关系。返回JSON格式:
{
  "relations": [
    {
      "source": "源概念",
      "target": "目标概念",
      "relation": "prerequisite|related|derived|component"
    }
  ]
}

说明:
- prerequisite: 前置关系，学习target需要先学习source
- related: 相关关系，两个概念有关联但无直接依赖
- derived: 衍生关系，target是从source发展而来
- component: 组成关系，target是source的组成部分`;

    const responseText = await this.ai!.chat([
      { role: 'system', content: '你是一位知识体系分析专家。' },
      { role: 'user', content: prompt }
    ], { temperature: 0.2 });

    const result = extractJson<{ relations?: Array<{ source: string; target: string; relation: string }> }>(responseText);

    if (result.success && result.data?.relations) {
      return result.data.relations;
    }

    console.error('Error parsing relations response:', result.error);
    return [];
  }

  /**
   * 对概念分类
   */
  private categorizeConcept(
    concept: string,
    relations: Array<{ source: string; target: string; relation: string }>
  ): 'foundation' | 'core' | 'advanced' | 'application' {
    // 基于关系数量判断类别
    const asSource = relations.filter(r => r.source === concept).length;
    const asTarget = relations.filter(r => r.target === concept).length;

    if (asSource > asTarget + 2) {
      return 'foundation';
    } else if (asTarget > asSource + 2) {
      return 'application';
    } else if (asSource + asTarget > 4) {
      return 'core';
    }
    return 'advanced';
  }

  /**
   * 计算概念重要性
   */
  private calculateImportance(
    concept: string,
    relations: Array<{ source: string; target: string; relation: string }>
  ): number {
    const degree = relations.filter(r => r.source === concept || r.target === concept).length;
    return Math.min(5, Math.max(1, degree));
  }

  /**
   * 构建聚类
   */
  private buildClusters(
    nodes: KnowledgeNode[],
    edges: KnowledgeEdge[]
  ): Map<string, string[]> {
    const clusters = new Map<string, string[]>();

    // 按类别聚类
    const categories = ['foundation', 'core', 'advanced', 'application'];
    for (const category of categories) {
      const clusterNodes = nodes.filter(n => n.category === category).map(n => n.id);
      if (clusterNodes.length > 0) {
        clusters.set(category, clusterNodes);
      }
    }

    return clusters;
  }

  /**
   * 发现学习路径
   */
  findPath(
    graph: KnowledgeGraphData,
    from: string,
    to: string
  ): string[] {
    const { nodes, edges } = graph;

    // BFS寻找路径
    const fromNode = nodes.find(n => n.label === from || n.id === from);
    const toNode = nodes.find(n => n.label === to || n.id === to);

    if (!fromNode || !toNode) return [];

    const visited = new Set<string>();
    const queue: Array<{ node: string; path: string[] }> = [
      { node: fromNode.id, path: [fromNode.label] }
    ];

    while (queue.length > 0) {
      const { node, path } = queue.shift()!;

      if (node === toNode.id) {
        return path;
      }

      if (visited.has(node)) continue;
      visited.add(node);

      // 找到相邻节点
      const neighbors = edges
        .filter(e => e.source === node)
        .map(e => e.target);

      for (const neighbor of neighbors) {
        if (!visited.has(neighbor)) {
          const neighborNode = nodes.find(n => n.id === neighbor);
          queue.push({
            node: neighbor,
            path: [...path, neighborNode?.label || neighbor]
          });
        }
      }
    }

    return [];
  }

  /**
   * 导出为Mermaid格式
   */
  toMermaid(graph: KnowledgeGraphData): string {
    const { nodes, edges } = graph;

    let mermaid = 'graph TD\n';

    // 添加节点
    for (const node of nodes) {
      const shape = this.getMermaidShape(node.category);
      mermaid += `    ${node.id}${shape.left}${node.label}${shape.right}\n`;
    }

    // 添加边
    for (const edge of edges) {
      const arrow = this.getMermaidArrow(edge.relation);
      mermaid += `    ${edge.source} ${arrow} ${edge.target}\n`;
    }

    // 添加样式
    mermaid += '\n    %% 样式定义\n';
    mermaid += '    classDef foundation fill:#e1f5fe,stroke:#01579b\n';
    mermaid += '    classDef core fill:#fff3e0,stroke:#e65100\n';
    mermaid += '    classDef advanced fill:#f3e5f5,stroke:#4a148c\n';
    mermaid += '    classDef application fill:#e8f5e9,stroke:#1b5e20\n';

    for (const node of nodes) {
      mermaid += `    class ${node.id} ${node.category}\n`;
    }

    return mermaid;
  }

  /**
   * 获取Mermaid节点形状
   */
  private getMermaidShape(category: string): { left: string; right: string } {
    switch (category) {
      case 'foundation':
        return { left: '[', right: ']' };
      case 'core':
        return { left: '((', right: '))' };
      case 'advanced':
        return { left: '{{', right: '}}' };
      case 'application':
        return { left: '[[', right: ']]' };
      default:
        return { left: '[', right: ']' };
    }
  }

  /**
   * 获取Mermaid箭头样式
   */
  private getMermaidArrow(relation: string): string {
    switch (relation) {
      case 'prerequisite':
        return '-->';
      case 'related':
        return '-.->';
      case 'derived':
        return '==>';
      case 'component':
        return '--o';
      default:
        return '-->';
    }
  }

  /**
   * 导出为JSON
   */
  toJSON(graph: KnowledgeGraphData): string {
    return JSON.stringify({
      nodes: graph.nodes,
      edges: graph.edges,
      clusters: Object.fromEntries(graph.clusters),
      literatureIndex: graph.literatureIndex ? {
        papers: Object.fromEntries(graph.literatureIndex.papers),
        paperToConcepts: Object.fromEntries(graph.literatureIndex.paperToConcepts)
      } : undefined,
      conceptIndex: graph.conceptIndex ? {
        conceptToPapers: Object.fromEntries(graph.conceptIndex.conceptToPapers)
      } : undefined,
      graphMetadata: graph.graphMetadata
    }, null, 2);
  }

  /**
   * 从JSON导入
   */
  fromJSON(json: string): KnowledgeGraphData {
    const data = JSON.parse(json);
    const result: KnowledgeGraphData = {
      nodes: data.nodes,
      edges: data.edges,
      clusters: new Map(Object.entries(data.clusters || {}))
    };

    if (data.literatureIndex) {
      result.literatureIndex = {
        papers: new Map(Object.entries(data.literatureIndex.papers || {})),
        paperToConcepts: new Map(Object.entries(data.literatureIndex.paperToConcepts || {}))
      };
    }

    if (data.conceptIndex) {
      result.conceptIndex = {
        conceptToPapers: new Map(Object.entries(data.conceptIndex.conceptToPapers || {}))
      };
    }

    if (data.graphMetadata) {
      result.graphMetadata = data.graphMetadata;
    }

    return result;
  }

  /**
   * 获取拓扑排序（学习顺序）
   */
  getTopologicalOrder(graph: KnowledgeGraphData): string[] {
    const { nodes, edges } = graph;
    const inDegree = new Map<string, number>();
    const adjacency = new Map<string, string[]>();

    // 初始化
    for (const node of nodes) {
      inDegree.set(node.id, 0);
      adjacency.set(node.id, []);
    }

    // 计算入度
    for (const edge of edges) {
      if (edge.relation === 'prerequisite' || edge.relation === 'component') {
        inDegree.set(edge.target, (inDegree.get(edge.target) || 0) + 1);
        adjacency.get(edge.source)?.push(edge.target);
      }
    }

    // Kahn算法
    const queue: string[] = [];
    const result: string[] = [];

    for (const [node, degree] of inDegree) {
      if (degree === 0) {
        queue.push(node);
      }
    }

    while (queue.length > 0) {
      const current = queue.shift()!;
      const nodeLabel = nodes.find(n => n.id === current)?.label || current;
      result.push(nodeLabel);

      for (const neighbor of adjacency.get(current) || []) {
        const newDegree = (inDegree.get(neighbor) || 0) - 1;
        inDegree.set(neighbor, newDegree);
        if (newDegree === 0) {
          queue.push(neighbor);
        }
      }
    }

    return result;
  }
}

// CLI 支持
if (import.meta.main) {
  const args = process.argv.slice(2);
  const concepts = args.filter(a => !a.startsWith('--'));
  const outputIndex = args.indexOf('--output');
  const outputFile = outputIndex > -1 ? args[outputIndex + 1] : null;
  const formatIndex = args.indexOf('--format');
  const format = formatIndex > -1 ? args[formatIndex + 1] : 'mermaid';

  if (concepts.length === 0) {
    console.error('Usage: graph.ts <concept1> <concept2> ... [--output <file>] [--format mermaid|json]');
    process.exit(1);
  }

  const builder = new KnowledgeGraphBuilder();

  builder.initialize().then(() => builder.build(concepts)).then(graph => {
    let output: string;

    if (format === 'json') {
      output = builder.toJSON(graph);
    } else {
      output = builder.toMermaid(graph);
    }

    if (outputFile) {
      const fs = require('fs');
      fs.writeFileSync(outputFile, output);
      console.log(`Graph saved to ${outputFile}`);
    } else {
      console.log(output);
    }
  }).catch(err => {
    console.error('Error:', getErrorMessage(err));
    process.exit(1);
  });
}

/**
 * Knowledge Graph Indexer - 双向索引系统
 * 构建概念→文献和文献→概念的双向索引
 * 支持按相关度、引用数、日期排序
 */

import type {
  KnowledgeGraphData,
  KnowledgeNode,
  PaperMetadata,
  LiteratureReference,
  LiteratureIndex,
  ConceptIndex
} from './graph';

/**
 * 论文查询选项
 */
export interface PaperQueryOptions {
  minRelevance?: number;
  sortBy?: 'relevance' | 'citations' | 'date';
  limit?: number;
  paperType?: 'review' | 'research' | 'all';
}

/**
 * 概念查询选项
 */
export interface ConceptQueryOptions {
  minRelevance?: number;
  sortBy?: 'relevance' | 'importance';
  limit?: number;
}

/**
 * 索引统计信息
 */
export interface IndexStatistics {
  totalConcepts: number;
  totalPapers: number;
  totalIndexEntries: number;
  avgPapersPerConcept: number;
  avgConceptsPerPaper: number;
  papersByType: { review: number; research: number };
}

/**
 * 带相关度的论文结果
 */
export interface PaperWithRelevance {
  paper: PaperMetadata;
  relevance: number;
  mentionType: string;
}

/**
 * 带相关度的概念结果
 */
export interface ConceptWithRelevance {
  concept: KnowledgeNode;
  relevance: number;
  mentionType: string;
}

export default class KnowledgeGraphIndexer {

  /**
   * 为图谱构建双向索引
   */
  buildIndex(graph: KnowledgeGraphData): KnowledgeGraphData {
    if (!graph.literatureIndex) {
      graph.literatureIndex = {
        papers: new Map(),
        paperToConcepts: new Map()
      };
    }
    if (!graph.conceptIndex) {
      graph.conceptIndex = {
        conceptToPapers: new Map()
      };
    }

    // 从节点的literatureReferences构建索引
    for (const node of graph.nodes) {
      if (!node.literatureReferences) continue;

      for (const ref of node.literatureReferences) {
        // 更新概念→论文索引
        const existingRefs = graph.conceptIndex.conceptToPapers.get(node.id) || [];
        if (!existingRefs.find(r => r.paperId === ref.paperId)) {
          existingRefs.push(ref);
          graph.conceptIndex.conceptToPapers.set(node.id, existingRefs);
        }

        // 更新论文→概念索引
        const existingConcepts = graph.literatureIndex.paperToConcepts.get(ref.paperId) || [];
        if (!existingConcepts.includes(node.id)) {
          existingConcepts.push(node.id);
          graph.literatureIndex.paperToConcepts.set(ref.paperId, existingConcepts);
        }
      }
    }

    return graph;
  }

  /**
   * 添加论文到索引
   */
  addPaperToIndex(
    graph: KnowledgeGraphData,
    conceptId: string,
    paper: PaperMetadata,
    reference: LiteratureReference
  ): void {
    if (!graph.literatureIndex) {
      graph.literatureIndex = { papers: new Map(), paperToConcepts: new Map() };
    }
    if (!graph.conceptIndex) {
      graph.conceptIndex = { conceptToPapers: new Map() };
    }

    // 存储论文元数据
    graph.literatureIndex.papers.set(paper.id, paper);

    // 更新概念→论文索引
    const refs = graph.conceptIndex.conceptToPapers.get(conceptId) || [];
    if (!refs.find(r => r.paperId === paper.id)) {
      refs.push(reference);
      graph.conceptIndex.conceptToPapers.set(conceptId, refs);
    }

    // 更新论文→概念索引
    const concepts = graph.literatureIndex.paperToConcepts.get(paper.id) || [];
    if (!concepts.includes(conceptId)) {
      concepts.push(conceptId);
      graph.literatureIndex.paperToConcepts.set(paper.id, concepts);
    }

    // 更新节点的literatureReferences
    const node = graph.nodes.find(n => n.id === conceptId);
    if (node) {
      if (!node.literatureReferences) node.literatureReferences = [];
      if (!node.literatureReferences.find(r => r.paperId === paper.id)) {
        node.literatureReferences.push(reference);
      }
      if (!node.keyPapers) node.keyPapers = [];
      if (!node.keyPapers.includes(paper.id)) {
        node.keyPapers.push(paper.id);
      }
    }
  }

  /**
   * 按概念查找论文
   */
  findPapersByConcept(
    graph: KnowledgeGraphData,
    conceptId: string,
    options: PaperQueryOptions = {}
  ): PaperWithRelevance[] {
    const {
      minRelevance = 0,
      sortBy = 'relevance',
      limit = 10,
      paperType = 'all'
    } = options;

    if (!graph.conceptIndex || !graph.literatureIndex) return [];

    const refs = graph.conceptIndex.conceptToPapers.get(conceptId) || [];
    let results: PaperWithRelevance[] = [];

    for (const ref of refs) {
      if (ref.relevance < minRelevance) continue;

      const paper = graph.literatureIndex.papers.get(ref.paperId);
      if (!paper) continue;
      if (paperType !== 'all' && paper.paperType !== paperType) continue;

      results.push({
        paper,
        relevance: ref.relevance,
        mentionType: ref.mentionType
      });
    }

    // 排序
    switch (sortBy) {
      case 'relevance':
        results.sort((a, b) => b.relevance - a.relevance);
        break;
      case 'citations':
        results.sort((a, b) => (b.paper.citations || 0) - (a.paper.citations || 0));
        break;
      case 'date':
        results.sort((a, b) =>
          new Date(b.paper.publishDate).getTime() - new Date(a.paper.publishDate).getTime()
        );
        break;
    }

    return results.slice(0, limit);
  }

  /**
   * 按论文查找概念
   */
  findConceptsByPaper(
    graph: KnowledgeGraphData,
    paperId: string,
    options: ConceptQueryOptions = {}
  ): ConceptWithRelevance[] {
    const { minRelevance = 0, sortBy = 'relevance', limit = 20 } = options;

    if (!graph.literatureIndex || !graph.conceptIndex) return [];

    const conceptIds = graph.literatureIndex.paperToConcepts.get(paperId) || [];
    let results: ConceptWithRelevance[] = [];

    for (const conceptId of conceptIds) {
      const node = graph.nodes.find(n => n.id === conceptId);
      if (!node) continue;

      // 找到该论文在该概念下的引用信息
      const refs = graph.conceptIndex.conceptToPapers.get(conceptId) || [];
      const ref = refs.find(r => r.paperId === paperId);
      const relevance = ref?.relevance || 0;

      if (relevance < minRelevance) continue;

      results.push({
        concept: node,
        relevance,
        mentionType: ref?.mentionType || 'related'
      });
    }

    // 排序
    switch (sortBy) {
      case 'relevance':
        results.sort((a, b) => b.relevance - a.relevance);
        break;
      case 'importance':
        results.sort((a, b) => b.concept.importance - a.concept.importance);
        break;
    }

    return results.slice(0, limit);
  }

  /**
   * 推荐论文（基于多个概念）
   */
  recommendPapers(
    graph: KnowledgeGraphData,
    conceptIds: string[],
    limit: number = 10
  ): PaperWithRelevance[] {
    if (!graph.conceptIndex || !graph.literatureIndex) return [];

    // 收集所有相关论文及其累计相关度
    const paperScores = new Map<string, { totalRelevance: number; matchedConcepts: number; mentionType: string }>();

    for (const conceptId of conceptIds) {
      const refs = graph.conceptIndex.conceptToPapers.get(conceptId) || [];
      for (const ref of refs) {
        const existing = paperScores.get(ref.paperId) || { totalRelevance: 0, matchedConcepts: 0, mentionType: ref.mentionType };
        existing.totalRelevance += ref.relevance;
        existing.matchedConcepts++;
        paperScores.set(ref.paperId, existing);
      }
    }

    // 构建结果，按综合评分排序
    const results: PaperWithRelevance[] = [];
    for (const [paperId, score] of paperScores) {
      const paper = graph.literatureIndex.papers.get(paperId);
      if (!paper) continue;

      // 综合评分 = 平均相关度 * 匹配概念比例
      const avgRelevance = score.totalRelevance / score.matchedConcepts;
      const coverageBonus = score.matchedConcepts / conceptIds.length;
      const compositeScore = avgRelevance * 0.6 + coverageBonus * 0.4;

      results.push({
        paper,
        relevance: Math.round(compositeScore * 100) / 100,
        mentionType: score.mentionType
      });
    }

    results.sort((a, b) => b.relevance - a.relevance);
    return results.slice(0, limit);
  }

  /**
   * 获取索引统计信息
   */
  getIndexStats(graph: KnowledgeGraphData): IndexStatistics {
    const totalConcepts = graph.nodes.length;
    let totalPapers = 0;
    let totalIndexEntries = 0;
    let reviewCount = 0;
    let researchCount = 0;

    if (graph.literatureIndex) {
      totalPapers = graph.literatureIndex.papers.size;
      for (const paper of graph.literatureIndex.papers.values()) {
        if (paper.paperType === 'review') reviewCount++;
        else researchCount++;
      }
      for (const concepts of graph.literatureIndex.paperToConcepts.values()) {
        totalIndexEntries += concepts.length;
      }
    }

    return {
      totalConcepts,
      totalPapers,
      totalIndexEntries,
      avgPapersPerConcept: totalConcepts > 0
        ? Math.round((totalIndexEntries / totalConcepts) * 10) / 10
        : 0,
      avgConceptsPerPaper: totalPapers > 0
        ? Math.round((totalIndexEntries / totalPapers) * 10) / 10
        : 0,
      papersByType: { review: reviewCount, research: researchCount }
    };
  }

  /**
   * 格式化统计信息
   */
  formatStats(stats: IndexStatistics): string {
    return `📊 图谱统计信息:
  概念数: ${stats.totalConcepts}
  文献数: ${stats.totalPapers} (综述: ${stats.papersByType.review}, 研究: ${stats.papersByType.research})
  索引条目: ${stats.totalIndexEntries}
  平均每概念关联论文: ${stats.avgPapersPerConcept}
  平均每论文关联概念: ${stats.avgConceptsPerPaper}`;
  }

  /**
   * 格式化概念查询结果
   */
  formatPaperResults(conceptLabel: string, results: PaperWithRelevance[]): string {
    const reviews = results.filter(r => r.paper.paperType === 'review');
    const research = results.filter(r => r.paper.paperType === 'research');

    const lines: string[] = [`🔍 "${conceptLabel}" 相关文献:\n`];

    if (reviews.length > 0) {
      lines.push(`📚 综述文献 (${reviews.length}篇):`);
      reviews.forEach((r, i) => {
        lines.push(`  ${i + 1}. ${r.paper.title} (相关度: ${(r.relevance * 100).toFixed(0)}%)`);
        lines.push(`     ${r.paper.url}`);
      });
      lines.push('');
    }

    if (research.length > 0) {
      lines.push(`📄 关键论文 (${research.length}篇):`);
      research.forEach((r, i) => {
        lines.push(`  ${i + 1}. ${r.paper.title} (相关度: ${(r.relevance * 100).toFixed(0)}%)`);
        if (r.paper.citations) {
          lines.push(`     引用: ${r.paper.citations} | ${r.paper.url}`);
        } else {
          lines.push(`     ${r.paper.url}`);
        }
      });
    }

    if (results.length === 0) {
      lines.push('  未找到相关文献');
    }

    return lines.join('\n');
  }
}

/**
 * Graph Storage - SQLite 持久化存储
 * 使用 bun:sqlite 实现知识图谱的持久化
 */

import { Database } from 'bun:sqlite';
import type {
  KnowledgeGraphData,
  KnowledgeNode,
  KnowledgeEdge,
  PaperMetadata,
  LiteratureReference,
  LiteratureIndex,
  ConceptIndex,
  GraphMetadata
} from './graph';

/** 数据库目录路径 */
const DEFAULT_DB_DIR = './data';
const DEFAULT_DB_NAME = 'knowledge-graphs.db';

export default class GraphStorage {
  private db: Database;

  constructor(dbPath?: string) {
    const path = dbPath || `${DEFAULT_DB_DIR}/${DEFAULT_DB_NAME}`;

    // 确保目录存在
    const fs = require('fs');
    const dir = path.substring(0, path.lastIndexOf('/'));
    if (dir && !fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }

    this.db = new Database(path);
    this.db.exec('PRAGMA journal_mode = WAL');
    this.db.exec('PRAGMA foreign_keys = ON');
    this.initSchema();
  }

  /**
   * 初始化数据库表结构
   */
  private initSchema(): void {
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS graphs (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT UNIQUE NOT NULL,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL,
        source_reviews TEXT,
        total_concepts INTEGER DEFAULT 0,
        total_papers INTEGER DEFAULT 0,
        total_relations INTEGER DEFAULT 0
      );

      CREATE TABLE IF NOT EXISTS nodes (
        id TEXT NOT NULL,
        graph_id INTEGER NOT NULL,
        label TEXT NOT NULL,
        category TEXT NOT NULL,
        importance INTEGER DEFAULT 1,
        description TEXT,
        definitions TEXT,
        key_papers TEXT,
        metadata TEXT,
        PRIMARY KEY (id, graph_id),
        FOREIGN KEY (graph_id) REFERENCES graphs(id) ON DELETE CASCADE
      );

      CREATE TABLE IF NOT EXISTS edges (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        graph_id INTEGER NOT NULL,
        source TEXT NOT NULL,
        target TEXT NOT NULL,
        relation TEXT NOT NULL,
        label TEXT,
        FOREIGN KEY (graph_id) REFERENCES graphs(id) ON DELETE CASCADE
      );

      CREATE TABLE IF NOT EXISTS papers (
        id TEXT NOT NULL,
        graph_id INTEGER NOT NULL,
        title TEXT NOT NULL,
        authors TEXT,
        abstract TEXT,
        publish_date TEXT,
        url TEXT,
        pdf_url TEXT,
        citations INTEGER,
        paper_type TEXT,
        keywords TEXT,
        metadata TEXT,
        PRIMARY KEY (id, graph_id),
        FOREIGN KEY (graph_id) REFERENCES graphs(id) ON DELETE CASCADE
      );

      CREATE TABLE IF NOT EXISTS concept_paper_index (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        graph_id INTEGER NOT NULL,
        concept_id TEXT NOT NULL,
        paper_id TEXT NOT NULL,
        relevance REAL NOT NULL,
        mention_type TEXT,
        mention_contexts TEXT,
        indexed_at TEXT NOT NULL,
        FOREIGN KEY (graph_id) REFERENCES graphs(id) ON DELETE CASCADE
      );

      CREATE INDEX IF NOT EXISTS idx_concept_paper ON concept_paper_index(graph_id, concept_id, relevance DESC);
      CREATE INDEX IF NOT EXISTS idx_paper_concept ON concept_paper_index(graph_id, paper_id);
      CREATE INDEX IF NOT EXISTS idx_nodes_graph ON nodes(graph_id);
      CREATE INDEX IF NOT EXISTS idx_edges_graph ON edges(graph_id);
      CREATE INDEX IF NOT EXISTS idx_papers_graph ON papers(graph_id);
    `);
  }

  /**
   * 保存图谱
   */
  saveGraph(graph: KnowledgeGraphData, name: string): void {
    const now = new Date().toISOString();
    const sourceReviews = graph.graphMetadata?.sourceReviews || [];

    const saveTransaction = this.db.transaction(() => {
      // 删除旧图谱（如果存在）
      const existing = this.db.query('SELECT id FROM graphs WHERE name = ?').get(name) as { id: number } | null;
      if (existing) {
        this.db.run('DELETE FROM graphs WHERE id = ?', [existing.id]);
      }

      // 插入图谱元数据
      this.db.run(
        `INSERT INTO graphs (name, created_at, updated_at, source_reviews, total_concepts, total_papers, total_relations)
         VALUES (?, ?, ?, ?, ?, ?, ?)`,
        [
          name,
          graph.graphMetadata?.createdAt || now,
          now,
          JSON.stringify(sourceReviews),
          graph.nodes.length,
          graph.literatureIndex?.papers.size || 0,
          graph.edges.length
        ]
      );

      const graphId = (this.db.query('SELECT last_insert_rowid() as id').get() as { id: number }).id;

      // 插入节点
      const insertNode = this.db.prepare(
        `INSERT INTO nodes (id, graph_id, label, category, importance, description, definitions, key_papers, metadata)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`
      );
      for (const node of graph.nodes) {
        insertNode.run(
          node.id,
          graphId,
          node.label,
          node.category,
          node.importance,
          node.description || null,
          node.definitions ? JSON.stringify(node.definitions) : null,
          node.keyPapers ? JSON.stringify(node.keyPapers) : null,
          node.metadata ? JSON.stringify(node.metadata) : null
        );
      }

      // 插入边
      const insertEdge = this.db.prepare(
        `INSERT INTO edges (graph_id, source, target, relation, label)
         VALUES (?, ?, ?, ?, ?)`
      );
      for (const edge of graph.edges) {
        insertEdge.run(graphId, edge.source, edge.target, edge.relation, edge.label || null);
      }

      // 插入文献
      if (graph.literatureIndex) {
        const insertPaper = this.db.prepare(
          `INSERT INTO papers (id, graph_id, title, authors, abstract, publish_date, url, pdf_url, citations, paper_type, keywords, metadata)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
        );
        for (const [paperId, paper] of graph.literatureIndex.papers) {
          insertPaper.run(
            paperId,
            graphId,
            paper.title,
            JSON.stringify(paper.authors),
            paper.abstract || null,
            paper.publishDate || null,
            paper.url || null,
            paper.pdfUrl || null,
            paper.citations || null,
            paper.paperType || null,
            JSON.stringify(paper.keywords || []),
            paper.metadata ? JSON.stringify(paper.metadata) : null
          );
        }
      }

      // 插入索引
      if (graph.conceptIndex) {
        const insertIndex = this.db.prepare(
          `INSERT INTO concept_paper_index (graph_id, concept_id, paper_id, relevance, mention_type, mention_contexts, indexed_at)
           VALUES (?, ?, ?, ?, ?, ?, ?)`
        );
        for (const [conceptId, refs] of graph.conceptIndex.conceptToPapers) {
          for (const ref of refs) {
            insertIndex.run(
              graphId,
              conceptId,
              ref.paperId,
              ref.relevance,
              ref.mentionType,
              JSON.stringify(ref.contexts || []),
              now
            );
          }
        }
      }
    });

    saveTransaction();
  }

  /**
   * 加载图谱
   */
  loadGraph(name: string): KnowledgeGraphData | null {
    const graphRow = this.db.query('SELECT * FROM graphs WHERE name = ?').get(name) as Record<string, any> | null;
    if (!graphRow) return null;

    const graphId = graphRow.id;

    // 加载节点
    const nodeRows = this.db.query('SELECT * FROM nodes WHERE graph_id = ?').all(graphId) as Record<string, any>[];
    const nodes: KnowledgeNode[] = nodeRows.map(row => ({
      id: row.id,
      label: row.label,
      category: row.category,
      importance: row.importance,
      description: row.description || undefined,
      definitions: row.definitions ? JSON.parse(row.definitions) : undefined,
      keyPapers: row.key_papers ? JSON.parse(row.key_papers) : undefined,
      metadata: row.metadata ? JSON.parse(row.metadata) : undefined,
      literatureReferences: []
    }));

    // 加载边
    const edgeRows = this.db.query('SELECT * FROM edges WHERE graph_id = ?').all(graphId) as Record<string, any>[];
    const edges: KnowledgeEdge[] = edgeRows.map(row => ({
      source: row.source,
      target: row.target,
      relation: row.relation,
      label: row.label || undefined
    }));

    // 加载文献
    const paperRows = this.db.query('SELECT * FROM papers WHERE graph_id = ?').all(graphId) as Record<string, any>[];
    const papers = new Map<string, PaperMetadata>();
    for (const row of paperRows) {
      papers.set(row.id, {
        id: row.id,
        title: row.title,
        authors: row.authors ? JSON.parse(row.authors) : [],
        abstract: row.abstract || '',
        publishDate: row.publish_date || '',
        url: row.url || '',
        pdfUrl: row.pdf_url || undefined,
        citations: row.citations || undefined,
        paperType: row.paper_type || 'research',
        keywords: row.keywords ? JSON.parse(row.keywords) : [],
        metadata: row.metadata ? JSON.parse(row.metadata) : undefined
      });
    }

    // 加载索引
    const indexRows = this.db.query('SELECT * FROM concept_paper_index WHERE graph_id = ?').all(graphId) as Record<string, any>[];

    const conceptToPapers = new Map<string, LiteratureReference[]>();
    const paperToConcepts = new Map<string, string[]>();

    for (const row of indexRows) {
      // 概念→论文
      const refs = conceptToPapers.get(row.concept_id) || [];
      refs.push({
        paperId: row.paper_id,
        title: papers.get(row.paper_id)?.title || '',
        relevance: row.relevance,
        mentionType: row.mention_type || 'foundational',
        contexts: row.mention_contexts ? JSON.parse(row.mention_contexts) : []
      });
      conceptToPapers.set(row.concept_id, refs);

      // 论文→概念
      const concepts = paperToConcepts.get(row.paper_id) || [];
      if (!concepts.includes(row.concept_id)) {
        concepts.push(row.concept_id);
        paperToConcepts.set(row.paper_id, concepts);
      }
    }

    // 设置节点的 literatureReferences
    for (const node of nodes) {
      node.literatureReferences = conceptToPapers.get(node.id) || [];
    }

    // 构建聚类
    const clusters = new Map<string, string[]>();
    for (const category of ['foundation', 'core', 'advanced', 'application']) {
      const categoryNodes = nodes.filter(n => n.category === category).map(n => n.id);
      if (categoryNodes.length > 0) {
        clusters.set(category, categoryNodes);
      }
    }

    return {
      nodes,
      edges,
      clusters,
      literatureIndex: { papers, paperToConcepts },
      conceptIndex: { conceptToPapers },
      graphMetadata: {
        name,
        createdAt: graphRow.created_at,
        updatedAt: graphRow.updated_at,
        sourceReviews: graphRow.source_reviews ? JSON.parse(graphRow.source_reviews) : [],
        totalConcepts: graphRow.total_concepts,
        totalPapers: graphRow.total_papers,
        totalRelations: graphRow.total_relations
      }
    };
  }

  /**
   * 列出所有图谱
   */
  listGraphs(): GraphMetadata[] {
    const rows = this.db.query('SELECT * FROM graphs ORDER BY updated_at DESC').all() as Record<string, any>[];
    return rows.map(row => ({
      name: row.name,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
      sourceReviews: row.source_reviews ? JSON.parse(row.source_reviews) : [],
      totalConcepts: row.total_concepts,
      totalPapers: row.total_papers,
      totalRelations: row.total_relations
    }));
  }

  /**
   * 删除图谱
   */
  deleteGraph(name: string): boolean {
    const result = this.db.run('DELETE FROM graphs WHERE name = ?', [name]);
    return result.changes > 0;
  }

  /**
   * 检查图谱是否存在
   */
  graphExists(name: string): boolean {
    const row = this.db.query('SELECT 1 FROM graphs WHERE name = ?').get(name);
    return row !== null;
  }

  /**
   * 通过SQL查询概念关联的论文（高性能）
   */
  queryPapersByConcept(
    graphName: string,
    conceptLabel: string,
    options: { minRelevance?: number; limit?: number; paperType?: string; sortBy?: string } = {}
  ): Array<PaperMetadata & { relevance: number; mentionType: string }> {
    const { minRelevance = 0, limit = 10, paperType, sortBy = 'relevance' } = options;

    let orderClause: string;
    switch (sortBy) {
      case 'citations': orderClause = 'p.citations DESC'; break;
      case 'date': orderClause = 'p.publish_date DESC'; break;
      default: orderClause = 'cpi.relevance DESC'; break;
    }

    let query = `
      SELECT p.*, cpi.relevance, cpi.mention_type
      FROM papers p
      JOIN concept_paper_index cpi ON p.id = cpi.paper_id AND p.graph_id = cpi.graph_id
      JOIN nodes n ON cpi.concept_id = n.id AND cpi.graph_id = n.graph_id
      JOIN graphs g ON g.id = p.graph_id
      WHERE g.name = ? AND n.label = ? AND cpi.relevance >= ?
    `;

    const params: any[] = [graphName, conceptLabel, minRelevance];

    if (paperType && paperType !== 'all') {
      query += ' AND p.paper_type = ?';
      params.push(paperType);
    }

    query += ` ORDER BY ${orderClause} LIMIT ?`;
    params.push(limit);

    const rows = this.db.query(query).all(...params) as Record<string, any>[];

    return rows.map(row => ({
      id: row.id,
      title: row.title,
      authors: row.authors ? JSON.parse(row.authors) : [],
      abstract: row.abstract || '',
      publishDate: row.publish_date || '',
      url: row.url || '',
      pdfUrl: row.pdf_url || undefined,
      citations: row.citations || undefined,
      paperType: row.paper_type || 'research',
      keywords: row.keywords ? JSON.parse(row.keywords) : [],
      relevance: row.relevance,
      mentionType: row.mention_type
    }));
  }

  /**
   * 通过SQL查询论文关联的概念（高性能）
   */
  queryConceptsByPaper(
    graphName: string,
    paperUrl: string
  ): Array<{ id: string; label: string; category: string; importance: number; relevance: number }> {
    const rows = this.db.query(`
      SELECT n.id, n.label, n.category, n.importance, cpi.relevance
      FROM nodes n
      JOIN concept_paper_index cpi ON n.id = cpi.concept_id AND n.graph_id = cpi.graph_id
      JOIN papers p ON cpi.paper_id = p.id AND cpi.graph_id = p.graph_id
      JOIN graphs g ON g.id = n.graph_id
      WHERE g.name = ? AND p.url = ?
      ORDER BY cpi.relevance DESC
    `).all(graphName, paperUrl) as Record<string, any>[];

    return rows.map(row => ({
      id: row.id,
      label: row.label,
      category: row.category,
      importance: row.importance,
      relevance: row.relevance
    }));
  }

  /**
   * 关闭数据库
   */
  close(): void {
    this.db.close();
  }
}
